-- 기존 2관 W01 김다인만 수정합니다. 학생/과목 열과 상담일지 테이블이 설치된 앱 프로젝트에서 실행하세요.
-- 문서 상담자 이름을 보존하며 로그인 계정에 과거 실적을 임의 귀속하지 않습니다.
begin;
lock table public.students, public.counseling_journals in share row exclusive mode;
do $import$
declare
  target_id uuid;
  matches integer;
  author_trigger "char";
  row_data jsonb;
begin
  if auth.uid() is not null then
    raise exception '이 SQL은 프로젝트 관리자의 SQL Editor 전용입니다.';
  end if;
  select count(*) into matches from public.students where name = '김다인' and building = 2 and seat_number = 'W01';
  if matches <> 1 then
    raise exception '기존 2관 W01 김다인 학생이 정확히 1명이어야 합니다. 현재 %명. 학생을 추가하지 않았습니다.', matches;
  end if;
  select id into target_id from public.students where name = '김다인' and building = 2 and seat_number = 'W01';
  if exists (select 1 from jsonb_array_elements('[{"date":"2026-03-09","original_date":"3.9","counselor_name":"박지수","content":"국어) 수특 문학- 중간까지 풀이 3개씩\n독서-초반까지 풀이 3개씩\n언매-초반까지 풀이\n수학) 수1- 수특 이번주까지 끝내기>>마더텅풀이\n수2-정승제 개념강의 다시시작함+ 수능특강 아직 초반\n확통- 수특 이번주까지 하기>>마더텅풀이\n영어) 수특 매일 10지문씩\n모의고사 이틀에 한번응시\n생윤) 자이스토리 이번주까지 끝내기\n윤사) 자이스토리풀이+ 김종익t 강의 + 수특","special_notes":"매쓰홀릭은 생략.."},{"date":"2026-03-18","original_date":"3.18","counselor_name":"이서화","content":"국어)\n수특 독서 매일 3지문 / 수특 문학 매일 6지문 / 수특 언매 15문제씩\n+ 1시간 이상씩 공부 중. 수특은 1/3 정도 함\n영어)\n수능 영어 독해 매일 10지문씩 / 영어 모의고사 중단 (수학에 집중)\n+ 1시간 이상씩 공부 중. 수특은 1/3 정도 함\n수학)\n마더텅 기출 문제 / 정승제 강의 + 오답노트\n+ 4-5시간씩 공부 중\n윤사, 생윤)\n수특 남은 단원 / 자이스토리\n+ 생윤 자이는 1단원 남음. 윤사와 생윤 3일에 1번 2시간 이상씩 공부 중","special_notes":"일일학습표 대신 플래너 작성 중\n국어 공부 시간 2시간은 유지하기\n생윤, 윤사 자이랑 수특 끝나면 오답 복습하면서 전체적으로 복습 예정"},{"date":"2026-04-01","original_date":"4.1","counselor_name":"이서화","content":"국어)\n수능특강 문학 끝내기 / 수능특강 독서 3지문씩 / 수능특강 언매 하루 2시간\n문학, 독서 수특 끝나면 인강 수강 예정\n영어)\n수능특강 영독연 10지문씩\n수학)\n마더텅 고난이도 문제 오답 노트 (수1, 수2, 확통) / 수능특강 오답 노트 + 2회독\n생윤)\n자이스토리 실전모의고사 10회 (하루 2회씩 5번)\n윤사)\n자이스토리 실전모의고사 10회 (하루 2회씩 5번)","special_notes":"하루에 최소 국어 2시간, 영어 1시간, 수학 3시간, 생윤 1시간, 윤사 1시간씩은 공부\n3월 모의고사) 국어3 수학3 영어2 생윤1 윤사2\n국어: 언매에서 2개 틀림. 언매 시간은 10분 정도 걸림. 비문학에서 틀림. 비문학 한 지문 못 읽음. 문학에서 시간이 좀 걸림.\n수학: 3점 문항 조금 틀림. 공통 4점 문항은 조금 풀 수 있음. 어3쉬4 연습해보기\n영어: 듣기 다 맞고 어려운 유형에서 틀림\n>> 딱히 크게 어려웠던 점 없음. 오답은 이번 주말에 해볼 예정"},{"date":"2026-04-10","original_date":"4.10","counselor_name":"최서원","content":"국어)\n수특 독서, 언매 풀기 > 수특 끝나면 김승리 ebs 연계 풀기\n문학 수특 완료 > 문학 김승리 ebs 연계 푸는 중\n수학)\n수특 수1, 수2, 확통 오답 복습 / 마더텅 풀기 / 기출의 미래 (기출문제집) 풀기\n영어)\n하루에 수특 영독연 Day 1개씩(12문제) 풀기\n단어는 모르는 단어 나오면 적어두고 따로 암기하는 중\n생윤,윤사)\n개념노트 보기 / 전에 풀었던 기출 문제 오답하기 (자이+수특)","special_notes":""},{"date":"2026-04-20","original_date":"4.20","counselor_name":"이서화","content":"국어)\n다담 문제집 언매 풀기 (20-30분) / 국어 모의고사 (김승리) 풀기 + 수능특강 문학 강의\n+ 수능특강 독서 이번주 완료\n수학)\n마더텅 모의고사 1회씩 풀기 (매일) / 수능특강 복습하기 (수1, 수2, 확통)\n+ 기출의 미래 완료\n영어)\n영어 모의고사 마더텅 1회씩 풀기 + 오답\n+ 수능특강 영독연 이번주 완료\n생윤, 윤사)\n마더텅 모의고사 1회씩 풀기 + 오답","special_notes":""},{"date":"2026-04-29","original_date":"4.29","counselor_name":"이서화","content":"국어)\n김승리 교재 매일승리 1회차씩 풀기 / 수능특강 독서 매일 1지문씩 풀어보기 / 다담 언매\n수능특강 문학은 완료.\n수학)\n마더텅 기출 (2-3일에 1회 1교시) + 오답노트 / 모의고사 1회씩\n수능특강 복습 완료.\n영어)\n매일 모의고사 1회씩 + 단어 모르는 부분 생기면 암기\n생윤, 윤사)\n모의고사 1회씩 격일로 + 문제집 병행 예정","special_notes":"국2 수3-4 영1.5 탐1 정도 비율로 공부 >> 국어 시간 조금만 늘리기\n생윤, 윤사 평가원 문제는 잘 맞는데 이번에 사설을 못 봄. >> 사설 성적에 너무 의미 부여할 필요 없음. 긴장감 느껴보고 시험 연습해보는 것에 집중하기"},{"date":"2026-05-07","original_date":"5.7","counselor_name":"최서원","content":"국어)\n언매 다담 문제집 풀기\n문학, 독서 김승리 ebs 연계강의 수강,문제집 풀기\n수특 복습\n수학)\n기출문제집 마더텅 풀기\n틀린 문제 오답 복습하기\n수특 2회독 중\n모의고사 1회씩(2일에 한 번정도)\n영어)\n모의고사 듣기 포함 매일 1회씩 풀기\n원래는 모르는 단어 나오면 따로 암기했었는데(10개정도)\n단어 암기량이 적은 느낌이 있어서 워드마스터2000 단어장에서 모르는 단어 매일 30개 정도씩 암기하는 방법을 권유함\n생윤, 윤사)\n모의고사 2일에 한번씩 풀기","special_notes":""},{"date":"2026-05-18","original_date":"5.18","counselor_name":"원문 미기재","content":"국어) 매월 승리 하루 1개씩\n독서 kbs 강의, 문제집 풀이량 50분정도로 늘려보기\n수학) 수특 전과목 2회독하기\n모의고사 매일 1회씩(킬러문항은 시간 좀 오래걸려도 됨)\n영어) 수특 2회독 매일 10지문씩, 모고 이틀에 한번, 워드마스터 모르는단어만 10개씩..(20개로 늘려보기)\n+문장삽입을 제일어려워함. 대표 전치사,접속사 별 문장흐름 따로 암기해보기\n생윤) 이틀에 한번 모의고사 + 오답\n윤사) 이틀에 한번 모의고사 + 오답","special_notes":"학습일정표 잘내기\n전과목 수능특강 1회독은 마무리"},{"date":"2026-06-04","original_date":"6.04","counselor_name":"원장","content":"-5월 대성 모의고사 상담\n-수학 수능 특강\nL1>>L2>대표>L3(수능 완성 병행)\n-국어 언매 매일 루팅\n-탐구 매일 루팅\n**오답 누적 복습\n-확통 문제 개별 풀이\n------","special_notes":""},{"date":"2026-06-19","original_date":"6.19","counselor_name":"최서원","content":"국어)\n수특 독서, 문학 김승리 강의 + 유형별 자이스토리 문제 풀기 + 다담 언매 복습\n수학)\n수능특강 수1, 수2, 확통 복습 (매일 8시간씩 공부)\n수특 끝나면 수능완성\n영어)\n자이스토리 유형별 기출 + 수능 특강\n생윤)\n3일에 한 번 마더텅 기출 1회씩\n윤사)\n3일에 한 번 마더텅 기출 1회씩","special_notes":"6모 성적\n국 수 영 윤사 생윤\n1/3/2/1/1\n5모 성적\n2/3/2/1/1"},{"date":"2026-07-20","original_date":"7.20","counselor_name":"최서원","content":"국어)\n수능특강 독서+수능완성 문학 (김승리 인강 + 2회독 복습중)\n언매: 수능완성\n수학)\n수능특강 복습 + 수능완성\n매일 5-6시간 학습\n어려운 4점 푸는 연습 하기. 최대한 해설지 보지 말고 스스로 발상 떠올리는 연습하기.\n영어)\n자이스토리 유형별 기출 문제집 3일에 한 번\n생윤)\n일주일에 한 번 모의고사 + 오답\n윤사)\n일주일에 한 번 모의고사 +  오답","special_notes":"7모\n국수영 생윤 윤사\n2 / 3(높은3) / 2(80초) / 1 / 1"},{"date":"2026-08-04","original_date":"8.4","counselor_name":"이서화","content":"국어)\n수능완성 강의 수강하기 (주에 2-3강 듣고 복습) / 수능완성 사용설명서\n영어)\n3일에 1번 모의고사 (듣기 포함)\n수학)\n수능특강, 수능완성 절반 끝내기 (수1, 수2, 확통)\n생윤, 윤사)\n이번주는 탐구 x","special_notes":""},{"date":"2026-08-11","original_date":"8.11","counselor_name":"최서원","content":"국어)\n수능완성 끝내기 + 김승리t 인강\n영어)\n수능완성, 모의고사 3일에 한 번 시간재고 풀기 / 모르는 단어만 암기중\n수학)\n수능완성 1회독 끝내기 / 모의고사(기출) 풀기\n생윤, 윤사)\n수능완성 3일에 한번씩","special_notes":"탐구 안정적임\n영어 안정2 나오도록 해보기\n국어1, 수학2 목표로 해보기"},{"date":"2026-08-25","original_date":"8.25","counselor_name":"최서원","content":"국어)\n언매 (다담) 복습하기 / 수특 독서 끝내기, 수특 수완 문학 복습하기 / 모의고사 기출 풀기(2일에 한 번)\n영어)\n수능완성 시작하기 + 단어 워드마스터 2000 하루에 100개 암기\n수학)\n수능완성 다 끝내기(실전모의고사 부분) + 2회독 하기\n윤사)\n수능완성 시작하기\n생윤)\n수능완성 시작하기","special_notes":""}]'::jsonb) x where (x->>'date')::date > (now() at time zone 'Asia/Seoul')::date) then
    raise exception '미래 상담일이 포함되어 있습니다. 연도를 확인하세요.';
  end if;
  update public.students set
    phone = '010-7113-4891', student_status = '재수생', school = '고양외고(졸)',
    korean_subject = '언어와 매체', math_subject = '확률과 통계',
    inquiry_subject_1 = '생활과 윤리', inquiry_subject_2 = '윤리와 사상'
  where id = target_id;

  -- 자동 로그인 상담자 지정 트리거만 트랜잭션 내에서 잠시 중지하고 원래 상태로 복구합니다.
  -- 외래키, 활동 로그, 그 외 트리거는 유지합니다.
  select tgenabled into author_trigger from pg_trigger
    where tgrelid = 'public.counseling_journals'::regclass and tgname = 'counseling_journals_author' and not tgisinternal;
  if author_trigger is not null then
    alter table public.counseling_journals disable trigger counseling_journals_author;
  end if;
  for row_data in select * from jsonb_array_elements('[{"date":"2026-03-09","original_date":"3.9","counselor_name":"박지수","content":"국어) 수특 문학- 중간까지 풀이 3개씩\n독서-초반까지 풀이 3개씩\n언매-초반까지 풀이\n수학) 수1- 수특 이번주까지 끝내기>>마더텅풀이\n수2-정승제 개념강의 다시시작함+ 수능특강 아직 초반\n확통- 수특 이번주까지 하기>>마더텅풀이\n영어) 수특 매일 10지문씩\n모의고사 이틀에 한번응시\n생윤) 자이스토리 이번주까지 끝내기\n윤사) 자이스토리풀이+ 김종익t 강의 + 수특","special_notes":"매쓰홀릭은 생략.."},{"date":"2026-03-18","original_date":"3.18","counselor_name":"이서화","content":"국어)\n수특 독서 매일 3지문 / 수특 문학 매일 6지문 / 수특 언매 15문제씩\n+ 1시간 이상씩 공부 중. 수특은 1/3 정도 함\n영어)\n수능 영어 독해 매일 10지문씩 / 영어 모의고사 중단 (수학에 집중)\n+ 1시간 이상씩 공부 중. 수특은 1/3 정도 함\n수학)\n마더텅 기출 문제 / 정승제 강의 + 오답노트\n+ 4-5시간씩 공부 중\n윤사, 생윤)\n수특 남은 단원 / 자이스토리\n+ 생윤 자이는 1단원 남음. 윤사와 생윤 3일에 1번 2시간 이상씩 공부 중","special_notes":"일일학습표 대신 플래너 작성 중\n국어 공부 시간 2시간은 유지하기\n생윤, 윤사 자이랑 수특 끝나면 오답 복습하면서 전체적으로 복습 예정"},{"date":"2026-04-01","original_date":"4.1","counselor_name":"이서화","content":"국어)\n수능특강 문학 끝내기 / 수능특강 독서 3지문씩 / 수능특강 언매 하루 2시간\n문학, 독서 수특 끝나면 인강 수강 예정\n영어)\n수능특강 영독연 10지문씩\n수학)\n마더텅 고난이도 문제 오답 노트 (수1, 수2, 확통) / 수능특강 오답 노트 + 2회독\n생윤)\n자이스토리 실전모의고사 10회 (하루 2회씩 5번)\n윤사)\n자이스토리 실전모의고사 10회 (하루 2회씩 5번)","special_notes":"하루에 최소 국어 2시간, 영어 1시간, 수학 3시간, 생윤 1시간, 윤사 1시간씩은 공부\n3월 모의고사) 국어3 수학3 영어2 생윤1 윤사2\n국어: 언매에서 2개 틀림. 언매 시간은 10분 정도 걸림. 비문학에서 틀림. 비문학 한 지문 못 읽음. 문학에서 시간이 좀 걸림.\n수학: 3점 문항 조금 틀림. 공통 4점 문항은 조금 풀 수 있음. 어3쉬4 연습해보기\n영어: 듣기 다 맞고 어려운 유형에서 틀림\n>> 딱히 크게 어려웠던 점 없음. 오답은 이번 주말에 해볼 예정"},{"date":"2026-04-10","original_date":"4.10","counselor_name":"최서원","content":"국어)\n수특 독서, 언매 풀기 > 수특 끝나면 김승리 ebs 연계 풀기\n문학 수특 완료 > 문학 김승리 ebs 연계 푸는 중\n수학)\n수특 수1, 수2, 확통 오답 복습 / 마더텅 풀기 / 기출의 미래 (기출문제집) 풀기\n영어)\n하루에 수특 영독연 Day 1개씩(12문제) 풀기\n단어는 모르는 단어 나오면 적어두고 따로 암기하는 중\n생윤,윤사)\n개념노트 보기 / 전에 풀었던 기출 문제 오답하기 (자이+수특)","special_notes":""},{"date":"2026-04-20","original_date":"4.20","counselor_name":"이서화","content":"국어)\n다담 문제집 언매 풀기 (20-30분) / 국어 모의고사 (김승리) 풀기 + 수능특강 문학 강의\n+ 수능특강 독서 이번주 완료\n수학)\n마더텅 모의고사 1회씩 풀기 (매일) / 수능특강 복습하기 (수1, 수2, 확통)\n+ 기출의 미래 완료\n영어)\n영어 모의고사 마더텅 1회씩 풀기 + 오답\n+ 수능특강 영독연 이번주 완료\n생윤, 윤사)\n마더텅 모의고사 1회씩 풀기 + 오답","special_notes":""},{"date":"2026-04-29","original_date":"4.29","counselor_name":"이서화","content":"국어)\n김승리 교재 매일승리 1회차씩 풀기 / 수능특강 독서 매일 1지문씩 풀어보기 / 다담 언매\n수능특강 문학은 완료.\n수학)\n마더텅 기출 (2-3일에 1회 1교시) + 오답노트 / 모의고사 1회씩\n수능특강 복습 완료.\n영어)\n매일 모의고사 1회씩 + 단어 모르는 부분 생기면 암기\n생윤, 윤사)\n모의고사 1회씩 격일로 + 문제집 병행 예정","special_notes":"국2 수3-4 영1.5 탐1 정도 비율로 공부 >> 국어 시간 조금만 늘리기\n생윤, 윤사 평가원 문제는 잘 맞는데 이번에 사설을 못 봄. >> 사설 성적에 너무 의미 부여할 필요 없음. 긴장감 느껴보고 시험 연습해보는 것에 집중하기"},{"date":"2026-05-07","original_date":"5.7","counselor_name":"최서원","content":"국어)\n언매 다담 문제집 풀기\n문학, 독서 김승리 ebs 연계강의 수강,문제집 풀기\n수특 복습\n수학)\n기출문제집 마더텅 풀기\n틀린 문제 오답 복습하기\n수특 2회독 중\n모의고사 1회씩(2일에 한 번정도)\n영어)\n모의고사 듣기 포함 매일 1회씩 풀기\n원래는 모르는 단어 나오면 따로 암기했었는데(10개정도)\n단어 암기량이 적은 느낌이 있어서 워드마스터2000 단어장에서 모르는 단어 매일 30개 정도씩 암기하는 방법을 권유함\n생윤, 윤사)\n모의고사 2일에 한번씩 풀기","special_notes":""},{"date":"2026-05-18","original_date":"5.18","counselor_name":"원문 미기재","content":"국어) 매월 승리 하루 1개씩\n독서 kbs 강의, 문제집 풀이량 50분정도로 늘려보기\n수학) 수특 전과목 2회독하기\n모의고사 매일 1회씩(킬러문항은 시간 좀 오래걸려도 됨)\n영어) 수특 2회독 매일 10지문씩, 모고 이틀에 한번, 워드마스터 모르는단어만 10개씩..(20개로 늘려보기)\n+문장삽입을 제일어려워함. 대표 전치사,접속사 별 문장흐름 따로 암기해보기\n생윤) 이틀에 한번 모의고사 + 오답\n윤사) 이틀에 한번 모의고사 + 오답","special_notes":"학습일정표 잘내기\n전과목 수능특강 1회독은 마무리"},{"date":"2026-06-04","original_date":"6.04","counselor_name":"원장","content":"-5월 대성 모의고사 상담\n-수학 수능 특강\nL1>>L2>대표>L3(수능 완성 병행)\n-국어 언매 매일 루팅\n-탐구 매일 루팅\n**오답 누적 복습\n-확통 문제 개별 풀이\n------","special_notes":""},{"date":"2026-06-19","original_date":"6.19","counselor_name":"최서원","content":"국어)\n수특 독서, 문학 김승리 강의 + 유형별 자이스토리 문제 풀기 + 다담 언매 복습\n수학)\n수능특강 수1, 수2, 확통 복습 (매일 8시간씩 공부)\n수특 끝나면 수능완성\n영어)\n자이스토리 유형별 기출 + 수능 특강\n생윤)\n3일에 한 번 마더텅 기출 1회씩\n윤사)\n3일에 한 번 마더텅 기출 1회씩","special_notes":"6모 성적\n국 수 영 윤사 생윤\n1/3/2/1/1\n5모 성적\n2/3/2/1/1"},{"date":"2026-07-20","original_date":"7.20","counselor_name":"최서원","content":"국어)\n수능특강 독서+수능완성 문학 (김승리 인강 + 2회독 복습중)\n언매: 수능완성\n수학)\n수능특강 복습 + 수능완성\n매일 5-6시간 학습\n어려운 4점 푸는 연습 하기. 최대한 해설지 보지 말고 스스로 발상 떠올리는 연습하기.\n영어)\n자이스토리 유형별 기출 문제집 3일에 한 번\n생윤)\n일주일에 한 번 모의고사 + 오답\n윤사)\n일주일에 한 번 모의고사 +  오답","special_notes":"7모\n국수영 생윤 윤사\n2 / 3(높은3) / 2(80초) / 1 / 1"},{"date":"2026-08-04","original_date":"8.4","counselor_name":"이서화","content":"국어)\n수능완성 강의 수강하기 (주에 2-3강 듣고 복습) / 수능완성 사용설명서\n영어)\n3일에 1번 모의고사 (듣기 포함)\n수학)\n수능특강, 수능완성 절반 끝내기 (수1, 수2, 확통)\n생윤, 윤사)\n이번주는 탐구 x","special_notes":""},{"date":"2026-08-11","original_date":"8.11","counselor_name":"최서원","content":"국어)\n수능완성 끝내기 + 김승리t 인강\n영어)\n수능완성, 모의고사 3일에 한 번 시간재고 풀기 / 모르는 단어만 암기중\n수학)\n수능완성 1회독 끝내기 / 모의고사(기출) 풀기\n생윤, 윤사)\n수능완성 3일에 한번씩","special_notes":"탐구 안정적임\n영어 안정2 나오도록 해보기\n국어1, 수학2 목표로 해보기"},{"date":"2026-08-25","original_date":"8.25","counselor_name":"최서원","content":"국어)\n언매 (다담) 복습하기 / 수특 독서 끝내기, 수특 수완 문학 복습하기 / 모의고사 기출 풀기(2일에 한 번)\n영어)\n수능완성 시작하기 + 단어 워드마스터 2000 하루에 100개 암기\n수학)\n수능완성 다 끝내기(실전모의고사 부분) + 2회독 하기\n윤사)\n수능완성 시작하기\n생윤)\n수능완성 시작하기","special_notes":""}]'::jsonb) loop
    if not exists (select 1 from public.counseling_journals where student_id = target_id and date = (row_data->>'date')::date) then
      insert into public.counseling_journals(student_id, date, counselor_id, counselor_name, content, special_notes, parent_message_sent)
      values (target_id, (row_data->>'date')::date, null, row_data->>'counselor_name', row_data->>'content', row_data->>'special_notes', false);
    end if;
  end loop;
  if author_trigger = 'O' then alter table public.counseling_journals enable trigger counseling_journals_author;
  elsif author_trigger = 'A' then alter table public.counseling_journals enable always trigger counseling_journals_author;
  elsif author_trigger = 'R' then alter table public.counseling_journals enable replica trigger counseling_journals_author;
  end if;
end;
$import$;
